async function build(D) {
  const NAME = D.name, X = D.x, Y = D.y, DARK = D.dark, page = figma.currentPage;
  for (const o of page.children.filter((n) => n.name === NAME)) o.remove();
  const FAM = { B: 'Bricolage Grotesque', S: 'IBM Plex Sans', M: 'IBM Plex Mono' };
  const sty = (f, w, it) => { const b = w >= 700 ? 'Bold' : w >= 600 ? 'SemiBold' : w >= 500 ? 'Medium' : 'Regular'; if (!it || f === 'B') return b; return b === 'Regular' ? 'Italic' : b + ' Italic'; };
  const fonts = D.st.map(([f, w, , , , , it]) => ({ family: FAM[f], style: sty(f, w, it) }));
  for (const fn of fonts) await figma.loadFontAsync(fn);
  for (const st of ['Regular', 'Medium', 'SemiBold', 'Bold']) { await figma.loadFontAsync({ family: 'IBM Plex Sans', style: st }); await figma.loadFontAsync({ family: 'IBM Plex Mono', style: st }); }
  const rgb = (c) => ({ r: c[0] / 255, g: c[1] / 255, b: c[2] / 255 });
  const paint = (c) => ({ type: 'SOLID', color: rgb(c), opacity: c[3] });
  const PX = 120, PY = 24;
  const frame = figma.createFrame(); frame.name = NAME; frame.resize(D.w + PX * 2, D.h + PY * 2); frame.x = X; frame.y = Y;
  const bgm = D.bg.match(/\d+/g).map(Number); frame.fills = [paint([bgm[0], bgm[1], bgm[2], 1])];
  const accent = DARK ? [224, 166, 60, 1] : [180, 119, 18, 1];
  let last = null;
  for (const n of D.n) {
    const k = n[0], x = n[1] + PX, y = n[2] + PY, w = Math.max(n[3], 0.5), h = Math.max(n[4], 0.5);
    if (k === 'r') {
      const [, , , , , bg, br, rad, gr, op, sh] = n;
      const r = figma.createRectangle(); r.name = 'box'; r.x = x; r.y = y; r.resize(w, h);
      const fills = []; if (bg) fills.push(paint(bg));
      if (gr) fills.push({ type: 'GRADIENT_LINEAR', gradientTransform: gr[0] === 'h' ? [[1, 0, 0], [0, 1, 0]] : [[0, 1, 0], [-1, 0, 1]], gradientStops: gr[1].map((c, i) => ({ position: i / (gr[1].length - 1), color: Object.assign(rgb(c), { a: c[3] }) })) });
      r.fills = fills;
      if (br) { r.strokes = [paint(br[1])]; r.strokeWeight = br[0]; r.strokeAlign = 'INSIDE'; if (br[2]) r.dashPattern = [5, 4]; }
      if (rad) r.cornerRadius = rad; if (op < 1) r.opacity = op;
      if (sh) r.effects = [{ type: 'DROP_SHADOW', color: { r: 0, g: 0, b: 0, a: 0.12 }, offset: { x: 0, y: 1 }, radius: 3, spread: 0, visible: true, blendMode: 'NORMAL' }];
      frame.appendChild(r); last = [r, n];
    } else if (k === 't') {
      const s = D.st[n[6]]; const t = figma.createText(); t.fontName = fonts[n[6]]; t.fontSize = s[2]; t.characters = n[5]; t.fills = [paint(s[3])];
      if (s[5]) t.letterSpacing = { unit: 'PIXELS', value: s[5] };
      frame.appendChild(t); t.x = x; t.y = y + (h - t.height) / 2;
      if (t.width > w + 3 && w > 20) { t.textAutoResize = 'NONE'; t.resize(w, t.height); t.textTruncation = 'ENDING'; }
    } else if (k === 'c') {
      const sz = 15, cx = x + (w - sz) / 2, cy = y + (h - sz) / 2;
      const b = n[6] ? figma.createEllipse() : figma.createRectangle(); b.name = n[5] ? 'checkbox on' : 'checkbox off';
      b.x = cx; b.y = cy; b.resize(sz, sz); if (!n[6]) b.cornerRadius = 3;
      if (n[5]) b.fills = [paint(DARK ? [57, 133, 255, 1] : [0, 117, 255, 1])];
      else { b.fills = [paint([255, 255, 255, 1])]; b.strokes = [paint([118, 118, 118, 1])]; b.strokeWeight = 1; b.strokeAlign = 'INSIDE'; }
      frame.appendChild(b);
      if (n[5]) { const t = figma.createText(); t.fontName = { family: 'IBM Plex Sans', style: 'Bold' }; t.fontSize = 11; t.characters = '✓'; t.fills = [paint([255, 255, 255, 1])]; frame.appendChild(t); t.x = cx + (sz - t.width) / 2; t.y = cy + (sz - t.height) / 2; }
    } else if (k === 'g') {
      if (last && last[1][1] === n[1] && last[1][2] === n[2]) last[0].remove();
      const f = n[5], cy = y + h / 2, ac = n[6] || accent;
      const tr = figma.createRectangle(); tr.name = 'slider track'; tr.x = x; tr.y = cy - 2; tr.resize(w, 4); tr.cornerRadius = 2; tr.fills = [paint(DARK ? [80, 88, 110, 1] : [206, 211, 220, 1])]; frame.appendChild(tr);
      const fl = figma.createRectangle(); fl.name = 'slider fill'; fl.x = x; fl.y = cy - 2; fl.resize(Math.max(1, w * f), 4); fl.cornerRadius = 2; fl.fills = [paint(ac)]; frame.appendChild(fl);
      const th = figma.createEllipse(); th.name = 'slider thumb'; th.resize(16, 16); th.x = x + (w - 16) * f; th.y = cy - 8; th.fills = [paint(ac)]; frame.appendChild(th);
    } else if (k === 'v') {
      const v = figma.createNodeFromSvg(n[5]); v.name = 'Fretboard'; frame.appendChild(v); v.x = x; v.y = y;
    }
  }
  return frame;
}

(async () => {
  try {
    let page = figma.root.children.find((p) => p.name === 'Hi-fi app screens');
    if (!page) { page = figma.createPage(); page.name = 'Hi-fi app screens'; }
    await figma.setCurrentPageAsync(page);
    const made = [];
    for (const s of SCREENS) { figma.notify('Building ' + s.name + '…', { timeout: 800 }); made.push(await build(s)); }
    figma.viewport.scrollAndZoomIntoView(made);
    figma.closePlugin('Built ' + made.length + ' screens on "Hi-fi app screens".');
  } catch (e) {
    figma.closePlugin('Could not build the screens: ' + (e && e.message ? e.message : e));
  }
})();
